        messages = result.get("Messages")
        if not messages:
            return None
        message = messages[0]
        receipt = message["ReceiptHandle"]
        self._client.delete_message(QueueUrl=self._queue_url, ReceiptHandle=receipt)
        return message["Body"]

    def health_check(self) -> bool:
        try:
            self._client.get_queue_attributes(QueueUrl=self._queue_url, AttributeNames=["ApproximateNumberOfMessages"])
            return True
        except (ClientError, BotoCoreError):
            LOGGER.exception("AWSQueueAdapter health check failed")
            return False


class AWSEventingAdapter(EventingAdapter):
    def __init__(
        self,
        event_bus_name: str,
        region: str,
        access_key: str,
        secret_key: str,
    ):
        self._event_bus = event_bus_name
        self._client = boto3.client(
            "events",
            region_name=region,
            aws_access_key_id=access_key,
            aws_secret_access_key=secret_key,
        )

    def publish_event(self, detail_type: str, payload: dict[str, Any]) -> str:
        response = self._client.put_events(
            Entries=[
                {
                    "Source": "zen2030.adapters",
                    "DetailType": detail_type,
                    "Detail": json.dumps(payload),
                    "EventBusName": self._event_bus,
                }
            ]
        )
        first = response["Entries"][0]
        return first.get("EventId", "")

    def health_check(self) -> bool:
        try:
            self._client.describe_event_bus(Name=self._event_bus)
            return True
        except (ClientError, BotoCoreError):
            LOGGER.exception("AWSEventingAdapter health check failed")
            return False


class AWSSecretsAdapter(SecretsAdapter):
    def __init__(
        self,
        secrets_prefix: str,
        region: str,
        access_key: str,
        secret_key: str,
    ):
        self._prefix = secrets_prefix.rstrip("/")
        self._client = boto3.client(
            "secretsmanager",
            region_name=region,
            aws_access_key_id=access_key,
            aws_secret_access_key=secret_key,
        )

    def get_secret(self, name: str) -> str:
        secret_name = f"{self._prefix}/{name}"
        response = self._client.get_secret_value(SecretId=secret_name)
        secret = response.get("SecretString")
        if secret is None:
            raise KeyError(f"Secret {secret_name} is empty")
        return secret

    def health_check(self) -> bool:
        try:
            self._client.get_secret_value(SecretId=self._prefix)
            return True
        except (ClientError, BotoCoreError):
            LOGGER.exception("AWSSecretsAdapter health check failed")
            return False


# --- On-prem adapters -------------------------------------------------------- #
class OnPremObjectStorageAdapter(ObjectStorageAdapter):
    def __init__(self, base_path: str):
        self._base_path = Path(base_path)
        self._base_path.mkdir(parents=True, exist_ok=True)

    def _file_path(self, key: str) -> Path:
        corrected = self._base_path / key
        corrected.parent.mkdir(parents=True, exist_ok=True)
        return corrected

    def upload(self, key: str, data: bytes) -> None:
        self._file_path(key).write_bytes(data)

    def download(self, key: str) -> bytes:
        return self._file_path(key).read_bytes()

    def delete(self, key: str) -> None:
        self._file_path(key).unlink(missing_ok=True)

    def health_check(self) -> bool:
        return self._base_path.exists()


class OnPremQueueAdapter(QueueAdapter):
    def __init__(self, db_path: str):
        self._db_path = Path(db_path)
        self._db_path.parent.mkdir(parents=True, exist_ok=True)
        self._conn = sqlite3.connect(str(self._db_path), check_same_thread=False)
        self._ensure_table()

    def _ensure_table(self) -> None:
        cursor = self._conn.cursor()
        cursor.execute(
            "CREATE TABLE IF NOT EXISTS queue (id INTEGER PRIMARY KEY AUTOINCREMENT, payload TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)"
        )
        self._conn.commit()

    def enqueue(self, payload: str) -> str:
        cursor = self._conn.cursor()
        cursor.execute("INSERT INTO queue (payload) VALUES (?)", (payload,))
        self._conn.commit()
        return str(cursor.lastrowid)

    def dequeue(self) -> str | None:
        cursor = self._conn.cursor()
        cursor.execute("SELECT id, payload FROM queue ORDER BY id ASC LIMIT 1")
        row = cursor.fetchone()
        if not row:
            return None
        queue_id, payload = row
        cursor.execute("DELETE FROM queue WHERE id = ?", (queue_id,))
        self._conn.commit()
        return payload

    def health_check(self) -> bool:
        try:
            cursor = self._conn.cursor()
            cursor.execute("SELECT 1")
            cursor.fetchone()
            return True
        except sqlite3.Error:
            LOGGER.exception("OnPremQueueAdapter health check failed")
            return False


class OnPremEventingAdapter(EventingAdapter):
    def __init__(self, log_dir: str):
        self._log_path = Path(log_dir)
        self._log_path.mkdir(parents=True, exist_ok=True)
        self._events_file = self._log_path / "events.log"
        self._events_file.touch(exist_ok=True)

    def publish_event(self, detail_type: str, payload: dict[str, Any]) -> str:
        entry = {"event_id": detail_type, "detail": payload}
        with self._events_file.open("a", encoding="utf-8") as stream:
            stream.write(json.dumps(entry) + "\n")
        return detail_type

    def health_check(self) -> bool:
        return self._events_file.exists()


class OnPremSecretsAdapter(SecretsAdapter):
    def __init__(self, secrets_file: str):
        self._secrets_path = Path(secrets_file)
        self._secrets_path.parent.mkdir(parents=True, exist_ok=True)
        if not self._secrets_path.exists():
            self._secrets_path.write_text(json.dumps({}), encoding="utf-8")

    def get_secret(self, name: str) -> str:
        with self._secrets_path.open("r", encoding="utf-8") as stream:
            data = json.load(stream)
        if name not in data:
            raise KeyError(f"Secret {name} not found in on-prem file")
        return str(data[name])

    def health_check(self) -> bool:
        return self._secrets_path.exists()


# --- Local adapters (MinIO + Redis) ------------------------------------------ #
class MinioObjectStorageAdapter(ObjectStorageAdapter):
    def __init__(
        self,
        endpoint: str,
        access_key: str,
        secret_key: str,
        bucket: str,
        secure: bool = False,
    ):
        self._bucket = bucket
        self._client = Minio(endpoint, access_key=access_key, secret_key=secret_key, secure=secure)
        if not self._client.bucket_exists(bucket):
            self._client.make_bucket(bucket)

    def upload(self, key: str, data: bytes) -> None:
        reader = io.BytesIO(data)
        self._client.put_object(bucket_name=self._bucket, object_name=key, data=reader, length=len(data))

    def download(self, key: str) -> bytes:
        response = self._client.get_object(bucket_name=self._bucket, object_name=key)
        try:
            return response.read()
        finally:
            response.close()
            response.release_conn()

    def delete(self, key: str) -> None:
        self._client.remove_object(bucket_name=self._bucket, object_name=key)

    def health_check(self) -> bool:
        try:
            return self._client.bucket_exists(self._bucket)
        except S3Error:
            LOGGER.exception("MinioObjectStorageAdapter health check failed")
            return False


class RedisQueueAdapter(QueueAdapter):
    def __init__(self, redis_url: str, queue_key: str):
        self._client = redis.Redis.from_url(redis_url)
        self._queue_key = queue_key

    def enqueue(self, payload: str) -> str:
        return str(self._client.rpush(self._queue_key, payload))

    def dequeue(self) -> str | None:
        result = self._client.lpop(self._queue_key)
        if result is None:
            return None
        if isinstance(result, bytes):
            return result.decode("utf-8")
        return str(result)

    def health_check(self) -> bool:
        try:
            return bool(self._client.ping())
        except redis.RedisError:
            LOGGER.exception("RedisQueueAdapter health check failed")
            return False


class RedisEventingAdapter(EventingAdapter):
    def __init__(self, redis_url: str, channel: str):
        self._client = redis.Redis.from_url(redis_url)
        self._channel = channel

    def publish_event(self, detail_type: str, payload: dict[str, Any]) -> str:
        message = json.dumps({"type": detail_type, "payload": payload})
        self._client.publish(self._channel, message)
        return detail_type

    def health_check(self) -> bool:
        try:
            return bool(self._client.ping())
        except redis.RedisError:
            LOGGER.exception("RedisEventingAdapter health check failed")
            return False


class EnvSecretsAdapter(SecretsAdapter):
    def __init__(self, prefix: str):
        self._prefix = prefix.rstrip("_")

    def get_secret(self, name: str) -> str:
        variable = f"{self._prefix}_{name}".upper()
        value = os.environ.get(variable)
        if value is None:
            raise KeyError(f"Environment secret {variable} is not set")
        return value

    def health_check(self) -> bool:
        # Passing if prefix exists in environment
        return any(key.startswith(f"{self._prefix}_") for key in os.environ)


# --- Resolution helpers ------------------------------------------------------ #
def resolve_adapters(settings: AdapterSettings) -> AdapterSuite:
    profile = settings.deployment_profile
    if profile == DeploymentProfile.AWS:
        return AdapterSuite(
            storage=AWSObjectStorageAdapter(
                bucket_name=settings.aws_storage_bucket,
                region=settings.aws_region,
                access_key=settings.aws_access_key_id,
                secret_key=settings.aws_secret_access_key,
            ),
            queue=AWSQueueAdapter(
                queue_url=settings.aws_queue_url,
                region=settings.aws_region,
                access_key=settings.aws_access_key_id,
                secret_key=settings.aws_secret_access_key,
            ),
            eventing=AWSEventingAdapter(
                event_bus_name=settings.aws_event_bus_name,
                region=settings.aws_region,
                access_key=settings.aws_access_key_id,
                secret_key=settings.aws_secret_access_key,
            ),
            secrets=AWSSecretsAdapter(
                secrets_prefix=settings.aws_secrets_prefix,
                region=settings.aws_region,
                access_key=settings.aws_access_key_id,
                secret_key=settings.aws_secret_access_key,
            ),
        )
    if profile == DeploymentProfile.ONPREM:
        return AdapterSuite(
            storage=OnPremObjectStorageAdapter(base_path=settings.onprem_storage_path),
            queue=OnPremQueueAdapter(db_path=settings.onprem_queue_db),
            eventing=OnPremEventingAdapter(log_dir=settings.onprem_event_log_dir),
            secrets=OnPremSecretsAdapter(secrets_file=settings.onprem_secrets_file),
        )
    if profile == DeploymentProfile.LOCAL:
        return AdapterSuite(
            storage=MinioObjectStorageAdapter(
                endpoint=settings.local_minio_endpoint,
                access_key=settings.local_minio_access_key,
                secret_key=settings.local_minio_secret_key,
                bucket=settings.local_minio_bucket,
                secure=settings.local_minio_secure,
            ),
            queue=RedisQueueAdapter(
                redis_url=settings.local_redis_url,
                queue_key=settings.local_redis_queue_key,
            ),
            eventing=RedisEventingAdapter(
                redis_url=settings.local_redis_url,
                channel=settings.local_redis_event_channel,
            ),
            secrets=EnvSecretsAdapter(prefix=settings.local_secret_prefix),
        )
    raise ValueError(f"Unsupported deployment profile: {profile}")
